// The landing page's benchmark rows are generated by bench/update-site.ts
// from bench/results.json. Two rules the owner set are pinned here: the
// baseline is THEORETICAL — the cold row's ideal schedule, and 0 for a
// cached run, a restore and CPU — and the site is what the generator
// produces (the docs gate's `site-check` task runs the same check; this
// pin reads the committed page so a hand edit fails in the core suite too).

import { readFileSync } from 'node:fs'
import path from 'node:path'
import { describe, expect, it } from 'bun:test'

const REPO = path.resolve(import.meta.dir, '../../..')

describe('landing page benchmark rows', () => {
  const page = readFileSync(path.join(REPO, 'apps/docs/src/pages/index.astro'), 'utf8')
  const results = JSON.parse(readFileSync(path.join(REPO, 'bench/results.json'), 'utf8')) as {
    baseline: { fresh: number }
  }
  const block = /const benchRows = \[\n([\s\S]*?)\n\]\n/.exec(page)![1]!
  const rows = [...block.matchAll(/task: '([^']+)',\n\s*bars: \[\n([\s\S]*?)\n\s*\],/g)].map(
    (m) => ({
      task: m[1]!,
      baseline: Number(/name: 'baseline', val: (\d+)/.exec(m[2]!)![1]),
    }),
  )

  it('has four rows, cold first', () => {
    expect(rows.map((r) => r.task)).toEqual([
      'Cold build · from scratch',
      'Fully cached · nothing to rebuild',
      'Restoring outputs · cache → disk',
      'CPU burned · cold build, user + system',
    ])
  })

  it("the baseline is theoretical: the cold row's ideal schedule, 0 everywhere else", () => {
    expect(rows[0]!.baseline).toBe(Math.round(results.baseline.fresh))
    expect(rows.slice(1).map((r) => r.baseline)).toEqual([0, 0, 0])
  })

  it('the chart draws true proportions: no minimum width, an outlier clipped', () => {
    // The rendering rule lives in Astro markup no test executes; pin its text.
    expect(page).toContain('const clipped = b.val > rowMax')
    expect(page).not.toMatch(/Math\.max\(\(b\.val \/ rowMax\) \* 100, \d+\)/)
  })
})
